from collections import deque

def window_max(nums, k):
    if k <= 0 or k > len(nums):
        return []
    q = deque()
    result = []
    for i in range(len(nums)):
        while q and nums[q[-1]] < nums[i]:
            q.pop()
        q.append(i)
        while q[0] < i - k + 1:
            q.popleft()
        if i >= k - 1:
            result.append(nums[q[0]])
    return result
